import { useState, useMemo } from 'react';
import { Table, Select, Input, Button, Modal, Form, InputNumber, Switch, Space, Empty } from 'antd';
import {
  SearchOutlined,
  ReloadOutlined,
  PlusOutlined,
  EditOutlined,
  DeleteOutlined,
} from '@ant-design/icons';
import {
  alertRules,
  alertRuleLevels,
  alertRuleDeviceTypes,
  alertRuleIndicators,
  alertRuleOperators,
  alertRuleHandlers,
  alertRuleNotifyMethods,
  AlertRuleItem,
} from '../data/dynamicMonitorData';

const AlertRule = () => {
  const [rules, setRules] = useState<AlertRuleItem[]>(alertRules);
  const [searchName, setSearchName] = useState('');
  const [modalVisible, setModalVisible] = useState(false);
  const [editingRule, setEditingRule] = useState<AlertRuleItem | null>(null);
  const [form] = Form.useForm();

  const filteredRules = useMemo(() => {
    return rules.filter((r) => {
      if (searchName && !r.ruleName.toLowerCase().includes(searchName.toLowerCase())) return false;
      return true;
    });
  }, [rules, searchName]);

  const levelColorMap: Record<string, string> = {
    紧急: 'bg-red-50 text-red-600 border border-red-200',
    重要: 'bg-orange-50 text-orange-600 border border-orange-200',
    次要: 'bg-yellow-50 text-yellow-600 border border-yellow-200',
    提示: 'bg-blue-50 text-blue-600 border border-blue-200',
  };

  const handleAdd = () => {
    setEditingRule(null);
    form.resetFields();
    form.setFieldsValue({
      alertLevel: '紧急',
      deviceType: '温湿度',
      alertIndicator: '温度',
      operator: '大于',
      threshold: 0,
      handler: '手动处理',
      enabled: true,
      notifyMethods: ['应用内消息'],
    });
    setModalVisible(true);
  };

  const handleEdit = (record: AlertRuleItem) => {
    setEditingRule(record);
    form.setFieldsValue({
      ...record,
      notifyMethods: ['应用内消息'],
    });
    setModalVisible(true);
  };

  const handleDelete = (id: number) => {
    setRules((prev) => prev.filter((r) => r.id !== id));
  };

  const handleToggleEnabled = (id: number, enabled: boolean) => {
    setRules((prev) => prev.map((r) => (r.id === id ? { ...r, enabled } : r)));
  };

  const handleSave = async () => {
    try {
      const values = await form.validateFields();
      if (editingRule) {
        // 编辑
        setRules((prev) =>
          prev.map((r) => (r.id === editingRule.id ? { ...r, ...values } : r))
        );
      } else {
        // 新增
        const newId = Math.max(...rules.map((r) => r.id), 0) + 1;
        setRules((prev) => [...prev, { id: newId, ...values }]);
      }
      setModalVisible(false);
    } catch {
      // 校验失败
    }
  };

  const resetSearch = () => {
    setSearchName('');
  };

  const columns = [
    {
      title: '序号',
      key: 'index',
      width: 60,
      render: (_: unknown, __: unknown, idx: number) => idx + 1,
    },
    { title: '规则名称', dataIndex: 'ruleName', key: 'ruleName', width: 200, sorter: (a: AlertRuleItem, b: AlertRuleItem) => a.ruleName.localeCompare(b.ruleName) },
    {
      title: '告警等级',
      dataIndex: 'alertLevel',
      key: 'alertLevel',
      width: 90,
      render: (level: string) => (
        <span className={`inline-block px-2 py-0.5 rounded text-xs font-medium ${levelColorMap[level] || ''}`}>
          {level}
        </span>
      ),
    },
    { title: '设备类型', dataIndex: 'deviceType', key: 'deviceType', width: 110 },
    { title: '告警指标', dataIndex: 'alertIndicator', key: 'alertIndicator', width: 100 },
    { title: '运算符', dataIndex: 'operator', key: 'operator', width: 90 },
    {
      title: '阈值',
      dataIndex: 'threshold',
      key: 'threshold',
      width: 80,
      sorter: (a: AlertRuleItem, b: AlertRuleItem) => a.threshold - b.threshold,
    },
    { title: '处理方', dataIndex: 'handler', key: 'handler', width: 100 },
    {
      title: '是否启用',
      dataIndex: 'enabled',
      key: 'enabled',
      width: 90,
      render: (enabled: boolean, record: AlertRuleItem) => (
        <Switch
          size="small"
          checked={enabled}
          onChange={(checked) => handleToggleEnabled(record.id, checked)}
        />
      ),
    },
    {
      title: '操作',
      key: 'action',
      width: 120,
      fixed: 'right' as const,
      render: (_: unknown, record: AlertRuleItem) => (
        <Space size="small">
          <Button type="link" size="small" icon={<EditOutlined />} className="px-1" onClick={() => handleEdit(record)}>编辑</Button>
          <Button type="link" size="small" danger icon={<DeleteOutlined />} className="px-1" onClick={() => handleDelete(record.id)}>删除</Button>
        </Space>
      ),
    },
  ];

  return (
    <div className="bg-gray-50 min-h-full">
      {/* Top bar (title area) */}
      <div className="bg-white border-b border-gray-200 px-6 py-3">
        <div className="flex items-center gap-2 text-sm text-gray-500">
          <span>动环监测</span>
          <span>/</span>
          <span>告警管理</span>
          <span>/</span>
          <span className="text-gray-800 font-medium">告警规则</span>
        </div>
      </div>

      <div className="p-6">
        <div className="bg-white rounded-lg border border-gray-200">
          {/* Filters & Action bar */}
          <div className="px-4 py-3 border-b border-gray-100">
            <div className="flex items-center gap-3 flex-wrap">
              <span className="text-sm text-gray-600">规则名称:</span>
              <Input
                placeholder="请输入"
                style={{ width: 200 }}
                value={searchName}
                onChange={(e) => setSearchName(e.target.value)}
                allowClear
              />
              <div className="ml-auto flex items-center gap-2">
                <Button type="primary" icon={<SearchOutlined />}>查询</Button>
                <Button icon={<ReloadOutlined />} onClick={resetSearch}>重置</Button>
                <Button type="primary" icon={<PlusOutlined />} onClick={handleAdd}>新增</Button>
              </div>
            </div>
          </div>

          {/* Table */}
          <div className="p-4">
            {filteredRules.length === 0 ? (
              <Empty description="暂无数据" />
            ) : (
              <Table
                columns={columns}
                dataSource={filteredRules}
                rowKey="id"
                size="middle"
                bordered
                scroll={{ x: 1200 }}
                pagination={{
                  pageSize: 20,
                  showSizeChanger: true,
                  showTotal: (total) => `共 ${total} 条`,
                }}
              />
            )}
          </div>
        </div>
      </div>

      {/* Add/Edit Modal */}
      <Modal
        title={editingRule ? '编辑规则' : '添加'}
        open={modalVisible}
        onCancel={() => setModalVisible(false)}
        onOk={handleSave}
        okText="保存"
        cancelText="取消"
        width={560}
        destroyOnClose
      >
        <Form
          form={form}
          layout="vertical"
          className="mt-4"
        >
          <div className="grid grid-cols-2 gap-x-4">
            <Form.Item
              label="规则名称"
              name="ruleName"
              rules={[{ required: true, message: '请输入规则名称' }]}
            >
              <Input placeholder="请输入规则名称" />
            </Form.Item>

            <Form.Item
              label="告警等级"
              name="alertLevel"
              rules={[{ required: true, message: '请选择告警等级' }]}
            >
              <Select options={alertRuleLevels.map((a) => ({ label: a, value: a }))} />
            </Form.Item>

            <Form.Item label="告警等级代码" name="alertLevelCode">
              <Input placeholder="请输入告警等级代码" />
            </Form.Item>

            <Form.Item
              label="设备类型"
              name="deviceType"
              rules={[{ required: true, message: '请选择设备类型' }]}
            >
              <Select options={alertRuleDeviceTypes.map((a) => ({ label: a, value: a }))} />
            </Form.Item>

            <Form.Item
              label="告警指标"
              name="alertIndicator"
              rules={[{ required: true, message: '请选择告警指标' }]}
            >
              <Select options={alertRuleIndicators.map((a) => ({ label: a, value: a }))} />
            </Form.Item>

            <Form.Item
              label="运算符"
              name="operator"
              rules={[{ required: true, message: '请选择运算符' }]}
            >
              <Select options={alertRuleOperators.map((a) => ({ label: a, value: a }))} />
            </Form.Item>

            <Form.Item
              label="告警值"
              name="threshold"
              rules={[{ required: true, message: '请输入告警值' }]}
            >
              <InputNumber className="w-full" placeholder="请输入告警值" />
            </Form.Item>

            <Form.Item label="持续时长" name="duration">
              <InputNumber className="w-full" placeholder="请输入持续时长(秒)" min={0} />
            </Form.Item>

            <Form.Item label="启用状态" name="enabled" valuePropName="checked">
              <Switch checkedChildren="启用" unCheckedChildren="禁用" />
            </Form.Item>

            <Form.Item
              label="处理方"
              name="handler"
              rules={[{ required: true, message: '请选择处理方' }]}
            >
              <Select options={alertRuleHandlers.map((a) => ({ label: a, value: a }))} />
            </Form.Item>
          </div>

          <Form.Item label="通知方式" name="notifyMethods">
            <Select
              mode="multiple"
              placeholder="请选择通知方式"
              options={alertRuleNotifyMethods.map((a) => ({ label: a, value: a }))}
            />
          </Form.Item>

          <Form.Item label="第三方告警接入" name="thirdPartyAccess">
            <Input placeholder="请输入第三方告警接入信息（可选）" />
          </Form.Item>
        </Form>
      </Modal>
    </div>
  );
};

export default AlertRule;
