import { useState, useEffect } from 'react';
import { Table, Button, Input, Select, DatePicker } from 'antd';
import { SearchOutlined, ReloadOutlined, ExportOutlined } from '@ant-design/icons';
import { WorkOrder } from '../types';
import { workOrders as initialWorkOrders } from '../data/mockData';
import { Dayjs } from 'dayjs';
import WorkOrderDetailModal from './WorkOrderDetailModal';
import WorkOrderDispatchModal from './WorkOrderDispatchModal';

const { Option } = Select;
const { RangePicker } = DatePicker;

const WorkOrderTracking = () => {
  const [workOrders] = useState<WorkOrder[]>(initialWorkOrders);
  const [filteredOrders, setFilteredOrders] = useState<WorkOrder[]>(initialWorkOrders);
  const [searchWorkOrderNo, setSearchWorkOrderNo] = useState('');
  const [workOrderType, setWorkOrderType] = useState('');
  const [workOrderSource, setWorkOrderSource] = useState('');
  const [priority, setPriority] = useState('');
  const [searchSubmitter, setSearchSubmitter] = useState('');
  const [dateRange, setDateRange] = useState<[Dayjs | null, Dayjs | null] | null>(null);
  const [pagination, setPagination] = useState({ current: 1, pageSize: 20 });
  const [detailModalVisible, setDetailModalVisible] = useState(false);
  const [dispatchModalVisible, setDispatchModalVisible] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState<WorkOrder | null>(null);

  useEffect(() => {
    let filtered = [...workOrders];

    if (searchWorkOrderNo) {
      filtered = filtered.filter(item =>
        item.workOrderNo.toLowerCase().includes(searchWorkOrderNo.toLowerCase()) ||
        item.workOrderTitle.toLowerCase().includes(searchWorkOrderNo.toLowerCase())
      );
    }

    if (workOrderType) {
      filtered = filtered.filter(item => item.workOrderType === workOrderType);
    }

    if (workOrderSource) {
      filtered = filtered.filter(item => item.workOrderSource === workOrderSource);
    }

    if (priority) {
      filtered = filtered.filter(item => item.priority === priority);
    }

    if (searchSubmitter) {
      filtered = filtered.filter(item =>
        item.submitter.toLowerCase().includes(searchSubmitter.toLowerCase()) ||
        item.submitterNo.toLowerCase().includes(searchSubmitter.toLowerCase())
      );
    }

    setFilteredOrders(filtered);
  }, [searchWorkOrderNo, workOrderType, workOrderSource, priority, searchSubmitter, dateRange, workOrders]);

  const handleSearch = () => {
    setPagination({ current: 1, pageSize: 20 });
  };

  const handleReset = () => {
    setSearchWorkOrderNo('');
    setWorkOrderType('');
    setWorkOrderSource('');
    setPriority('');
    setSearchSubmitter('');
    setDateRange(null);
    setPagination({ current: 1, pageSize: 20 });
  };

  const handleExport = () => {
    alert('导出功能');
  };

  const handleDetail = (record: WorkOrder) => {
    setSelectedOrder(record);
    setDetailModalVisible(true);
  };

  const handleDispatch = (record: WorkOrder) => {
    setSelectedOrder(record);
    setDispatchModalVisible(true);
  };

  const columns = [
    {
      title: '序号',
      dataIndex: 'id',
      key: 'id',
      width: 60,
      render: (_: unknown, __: unknown, index: number) => (pagination.current - 1) * pagination.pageSize + index + 1,
    },
    {
      title: '工单号',
      dataIndex: 'workOrderNo',
      key: 'workOrderNo',
      ellipsis: true,
      sorter: (a: WorkOrder, b: WorkOrder) => a.workOrderNo.localeCompare(b.workOrderNo),
    },
    {
      title: '工单标题',
      dataIndex: 'workOrderTitle',
      key: 'workOrderTitle',
      ellipsis: true,
      sorter: (a: WorkOrder, b: WorkOrder) => a.workOrderTitle.localeCompare(b.workOrderTitle),
    },
    {
      title: '工单类型',
      dataIndex: 'workOrderType',
      key: 'workOrderType',
      sorter: (a: WorkOrder, b: WorkOrder) => a.workOrderType.localeCompare(b.workOrderType),
    },
    {
      title: '工单来源',
      dataIndex: 'workOrderSource',
      key: 'workOrderSource',
      sorter: (a: WorkOrder, b: WorkOrder) => a.workOrderSource.localeCompare(b.workOrderSource),
    },
    {
      title: '优先级',
      dataIndex: 'priority',
      key: 'priority',
      sorter: (a: WorkOrder, b: WorkOrder) => a.priority.localeCompare(b.priority),
      render: (priority: string) => (
        <span className={priority === '紧急工单' ? 'text-red-600 font-medium' : ''}>
          {priority}
        </span>
      ),
    },
    {
      title: '提交人',
      dataIndex: 'submitter',
      key: 'submitter',
      sorter: (a: WorkOrder, b: WorkOrder) => a.submitter.localeCompare(b.submitter),
    },
    {
      title: '提交人工号',
      dataIndex: 'submitterNo',
      key: 'submitterNo',
      sorter: (a: WorkOrder, b: WorkOrder) => a.submitterNo.localeCompare(b.submitterNo),
    },
    {
      title: '提交人组织',
      dataIndex: 'submitterOrg',
      key: 'submitterOrg',
      sorter: (a: WorkOrder, b: WorkOrder) => a.submitterOrg.localeCompare(b.submitterOrg),
    },
    {
      title: '提交时间',
      dataIndex: 'submitTime',
      key: 'submitTime',
      sorter: (a: WorkOrder, b: WorkOrder) => a.submitTime.localeCompare(b.submitTime),
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      sorter: (a: WorkOrder, b: WorkOrder) => a.status.localeCompare(b.status),
      render: (status: string) => (
        <span className="inline-block px-2 py-0.5 bg-orange-100 text-orange-700 rounded text-sm font-medium">
          {status}
        </span>
      ),
    },
    {
      title: '当前处理人',
      dataIndex: 'currentHandler',
      key: 'currentHandler',
      sorter: (a: WorkOrder, b: WorkOrder) => a.currentHandler.localeCompare(b.currentHandler),
    },
    {
      title: '操作',
      key: 'action',
      width: 120,
      render: (_: string, record: WorkOrder) => (
        <div className="flex items-center space-x-2">
          <Button type="link" size="small" onClick={() => handleDetail(record)}>详情</Button>
          <Button type="link" size="small" onClick={() => handleDispatch(record)}>转派</Button>
        </div>
      ),
    },
  ];

  const workOrderTypeOptions = Array.from(new Set(initialWorkOrders.map(order => order.workOrderType)));
  const workOrderSourceOptions = Array.from(new Set(initialWorkOrders.map(order => order.workOrderSource)));
  const priorityOptions = Array.from(new Set(initialWorkOrders.map(order => order.priority)));

  return (
    <div className="p-4">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center space-x-4">
          <div className="flex items-center">
            <span className="mr-2 text-gray-600">工单</span>
            <Input
              placeholder="工单号/标题"
              value={searchWorkOrderNo}
              onChange={(e) => setSearchWorkOrderNo(e.target.value)}
              onPressEnter={handleSearch}
              style={{ width: 200 }}
            />
          </div>
          <div className="flex items-center">
            <span className="mr-2 text-gray-600">工单类型</span>
            <Select
              placeholder="请选择"
              value={workOrderType}
              onChange={setWorkOrderType}
              style={{ width: 150 }}
            >
              {workOrderTypeOptions.map(opt => (
                <Option key={opt} value={opt}>{opt}</Option>
              ))}
            </Select>
          </div>
          <div className="flex items-center">
            <span className="mr-2 text-gray-600">工单来源</span>
            <Select
              placeholder="请选择"
              value={workOrderSource}
              onChange={setWorkOrderSource}
              style={{ width: 150 }}
            >
              {workOrderSourceOptions.map(opt => (
                <Option key={opt} value={opt}>{opt}</Option>
              ))}
            </Select>
          </div>
          <div className="flex items-center">
            <span className="mr-2 text-gray-600">优先级</span>
            <Select
              placeholder="请选择"
              value={priority}
              onChange={setPriority}
              style={{ width: 150 }}
            >
              {priorityOptions.map(opt => (
                <Option key={opt} value={opt}>{opt}</Option>
              ))}
            </Select>
          </div>
        </div>
        <div className="flex items-center space-x-4">
          <div className="flex items-center">
            <span className="mr-2 text-gray-600">提交人</span>
            <Input
              placeholder="提交人工号/姓名"
              value={searchSubmitter}
              onChange={(e) => setSearchSubmitter(e.target.value)}
              onPressEnter={handleSearch}
              style={{ width: 200 }}
            />
          </div>
          <div className="flex items-center">
            <span className="mr-2 text-gray-600">提交时间</span>
            <RangePicker
              value={dateRange}
              onChange={(dates) => setDateRange(dates)}
              style={{ width: 300 }}
            />
          </div>
          <div className="flex items-center space-x-2">
            <Button
              type="primary"
              icon={<SearchOutlined />}
              onClick={handleSearch}
            >
              查询
            </Button>
            <Button
              icon={<ReloadOutlined />}
              onClick={handleReset}
            >
              重置
            </Button>
            <Button
              type="primary"
              icon={<ExportOutlined />}
              onClick={handleExport}
            >
              导出
            </Button>
          </div>
        </div>
      </div>
      <Table
        columns={columns}
        dataSource={filteredOrders}
        rowKey="id"
        pagination={{
          ...pagination,
          total: filteredOrders.length,
          onChange: (page, pageSize) => setPagination({ current: page, pageSize }),
          showSizeChanger: true,
          pageSizeOptions: ['10', '20', '50', '100'],
          showTotal: (total) => `共 ${total} 条`,
        }}
        bordered
        scroll={{ x: 1800 }}
      />
      <WorkOrderDetailModal
        open={detailModalVisible}
        order={selectedOrder}
        onCancel={() => setDetailModalVisible(false)}
      />
      <WorkOrderDispatchModal
        open={dispatchModalVisible}
        order={selectedOrder}
        onCancel={() => setDispatchModalVisible(false)}
      />
    </div>
  );
};

export default WorkOrderTracking;