import { useState, useMemo } from 'react';
import { Table, Select, Input, Button, DatePicker, Empty, Space } from 'antd';
import dayjs from 'dayjs';
import {
  SearchOutlined,
  ReloadOutlined,
  ThunderboltOutlined,
} from '@ant-design/icons';
import {
  alertRecords,
  alertRecordDeviceTypes,
  alertRecordLevels,
  alertRecordStatuses,
  AlertRecordItem,
} from '../data/dynamicMonitorData';

const AlertRecord = () => {
  // Filters
  const [deviceType, setDeviceType] = useState<string | undefined>(undefined);
  const [alertLevel, setAlertLevel] = useState<string | undefined>(undefined);
  const [deviceName, setDeviceName] = useState('');
  const [alertStatus, setAlertStatus] = useState<string | undefined>(undefined);
  const [alertRange, setAlertRange] = useState<dayjs.Dayjs | null>(null);

  // Selected rows
  const [selectedRowKeys, setSelectedRowKeys] = useState<React.Key[]>([]);

  const filteredRecords = useMemo(() => {
    return alertRecords.filter((d) => {
      if (deviceType && d.deviceSource !== deviceType) return false;
      if (alertLevel && d.alertLevel !== alertLevel) return false;
      if (alertStatus && d.alertStatus !== alertStatus) return false;
      if (deviceName && !d.deviceName.toLowerCase().includes(deviceName.toLowerCase())) return false;
      return true;
    });
  }, [deviceType, alertLevel, alertStatus, deviceName]);

  const resetFilters = () => {
    setDeviceType(undefined);
    setAlertLevel(undefined);
    setDeviceName('');
    setAlertStatus(undefined);
    setAlertRange(null);
  };

  const levelColorMap: Record<string, string> = {
    紧急: 'bg-red-50 text-red-600 border border-red-200',
    重要: 'bg-orange-50 text-orange-600 border border-orange-200',
    次要: 'bg-yellow-50 text-yellow-600 border border-yellow-200',
    提示: 'bg-blue-50 text-blue-600 border border-blue-200',
  };

  const statusColorMap: Record<string, string> = {
    未处理: 'bg-red-50 text-red-600 border border-red-200',
    已处理: 'bg-green-50 text-green-600 border border-green-200',
    已忽略: 'bg-gray-100 text-gray-500 border border-gray-200',
  };

  const columns = [
    {
      title: '告警设备',
      dataIndex: 'deviceName',
      key: 'deviceName',
      width: 180,
      sorter: (a: AlertRecordItem, b: AlertRecordItem) => a.deviceName.localeCompare(b.deviceName),
    },
    {
      title: '告警状态',
      dataIndex: 'alertStatus',
      key: 'alertStatus',
      width: 90,
      render: (status: string) => (
        <span className={`inline-block px-2 py-0.5 rounded text-xs font-medium ${statusColorMap[status] || ''}`}>
          {status}
        </span>
      ),
    },
    {
      title: '告警指标',
      dataIndex: 'alertIndicator',
      key: 'alertIndicator',
      width: 100,
    },
    {
      title: '描述',
      dataIndex: 'description',
      key: 'description',
      width: 160,
    },
    {
      title: '设备来源',
      dataIndex: 'deviceSource',
      key: 'deviceSource',
      width: 110,
    },
    {
      title: '告警等级',
      dataIndex: 'alertLevel',
      key: 'alertLevel',
      width: 90,
      render: (level: string) => (
        <span className={`inline-block px-2 py-0.5 rounded text-xs font-medium ${levelColorMap[level] || ''}`}>
          {level}
        </span>
      ),
    },
    {
      title: '处理方法',
      dataIndex: 'handleMethod',
      key: 'handleMethod',
      width: 100,
    },
    {
      title: '告警时间',
      dataIndex: 'alertTime',
      key: 'alertTime',
      width: 160,
      sorter: (a: AlertRecordItem, b: AlertRecordItem) => a.alertTime.localeCompare(b.alertTime),
    },
    {
      title: '处理结果',
      dataIndex: 'handleResult',
      key: 'handleResult',
      width: 100,
    },
    {
      title: '处理时间',
      dataIndex: 'handleTime',
      key: 'handleTime',
      width: 160,
    },
    {
      title: '操作',
      key: 'action',
      width: 120,
      fixed: 'right' as const,
      render: (_: unknown, record: AlertRecordItem) => (
        <Space size="small">
          <Button type="link" size="small" className="px-1">处理</Button>
          <Button type="link" size="small" className="px-1">详情</Button>
        </Space>
      ),
    },
  ];

  return (
    <div className="bg-gray-50 min-h-full">
      {/* Top bar (title area) */}
      <div className="bg-white border-b border-gray-200 px-6 py-3">
        <div className="flex items-center gap-2 text-sm text-gray-500">
          <span>动环监测</span>
          <span>/</span>
          <span>告警管理</span>
          <span>/</span>
          <span className="text-gray-800 font-medium">告警记录</span>
        </div>
      </div>

      <div className="p-6">
        <div className="bg-white rounded-lg border border-gray-200">
          {/* Filters & Action bar */}
          <div className="px-4 py-3 border-b border-gray-100">
            <div className="flex items-center gap-3 flex-wrap">
              <span className="text-sm text-gray-600">设备类型:</span>
              <Select
                allowClear
                placeholder="请选择"
                style={{ width: 150 }}
                value={deviceType}
                onChange={(v) => setDeviceType(v)}
                options={alertRecordDeviceTypes.map((a) => ({ label: a, value: a }))}
              />
              <span className="text-sm text-gray-600 ml-2">告警等级:</span>
              <Select
                allowClear
                placeholder="请选择"
                style={{ width: 150 }}
                value={alertLevel}
                onChange={(v) => setAlertLevel(v)}
                options={alertRecordLevels.map((a) => ({ label: a, value: a }))}
              />
              <span className="text-sm text-gray-600 ml-2">设备名称:</span>
              <Input
                placeholder="请输入"
                style={{ width: 180 }}
                value={deviceName}
                onChange={(e) => setDeviceName(e.target.value)}
                allowClear
              />
              <span className="text-sm text-gray-600 ml-2">告警时间:</span>
              <DatePicker
                value={alertRange}
                onChange={(d) => setAlertRange(d as dayjs.Dayjs | null)}
                placeholder="选择日期"
              />
              <span className="text-sm text-gray-600 ml-2">告警状态:</span>
              <Select
                allowClear
                placeholder="请选择"
                style={{ width: 150 }}
                value={alertStatus}
                onChange={(v) => setAlertStatus(v)}
                options={alertRecordStatuses.map((a) => ({ label: a, value: a }))}
              />
              <div className="ml-auto flex items-center gap-2">
                <Button type="primary" icon={<SearchOutlined />}>查询</Button>
                <Button icon={<ReloadOutlined />} onClick={resetFilters}>重置</Button>
                <Button icon={<ThunderboltOutlined />}>批量处理</Button>
              </div>
            </div>
          </div>

          {/* Table */}
          <div className="p-4">
            {filteredRecords.length === 0 ? (
              <Empty description="暂无数据" />
            ) : (
              <Table
                columns={columns}
                dataSource={filteredRecords}
                rowKey="id"
                size="middle"
                bordered
                scroll={{ x: 1400 }}
                rowSelection={{
                  selectedRowKeys,
                  onChange: setSelectedRowKeys,
                }}
                pagination={{
                  pageSize: 20,
                  showSizeChanger: true,
                  showTotal: (total) => `共 ${total} 条`,
                }}
              />
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AlertRecord;
