import { useState } from 'react';
import { Modal, Form, Input, Select, Button, message } from 'antd';
import { WorkOrder } from '../types';

interface WorkOrderDispatchModalProps {
  open: boolean;
  order: WorkOrder | null;
  onCancel: () => void;
}

const { Option } = Select;

const WorkOrderDispatchModal = ({ open, order, onCancel }: WorkOrderDispatchModalProps) => {
  const [form] = Form.useForm();
  const [dispatchReason, setDispatchReason] = useState('');

  const handleOk = () => {
    form.validateFields().then(values => {
      message.success('转派成功');
      onCancel();
      form.resetFields();
      setDispatchReason('');
    }).catch(() => {
      message.error('请填写必填项');
    });
  };

  const handleCancel = () => {
    onCancel();
    form.resetFields();
    setDispatchReason('');
  };

  const handlerOptions = [
    { value: 'admin', label: '管理员' },
    { value: 'user1', label: '张三' },
    { value: 'user2', label: '李四' },
    { value: 'user3', label: '王五' },
  ];

  return (
    <Modal
      forceRender
      getContainer={false}
      title="转派"
      open={open}
      onCancel={handleCancel}
      footer={[
        <Button key="back" onClick={handleCancel}>
          取消
        </Button>,
        <Button key="submit" type="primary" onClick={handleOk}>
          保存
        </Button>,
      ]}
      width={450}
      style={{ zIndex: 9999 }}
    >
      <Form form={form} layout="vertical">
        <Form.Item label="当前处理人">
          <Input placeholder="请输入" disabled />
        </Form.Item>

        <Form.Item
          label="转派后处理人员"
          name="handler"
          rules={[{ required: true, message: '请选择转派后处理人员' }]}
        >
          <Select placeholder="请选择">
            {handlerOptions.map(opt => (
              <Option key={opt.value} value={opt.value}>{opt.label}</Option>
            ))}
          </Select>
        </Form.Item>

        <Form.Item label="转派说明">
          <Input.TextArea
            placeholder="请输入"
            value={dispatchReason}
            onChange={(e) => setDispatchReason(e.target.value)}
            maxLength={200}
            showCount
            style={{ height: 100 }}
          />
        </Form.Item>
      </Form>
    </Modal>
  );
};

export default WorkOrderDispatchModal;